var i=`rpc-and-grpc`;var n=63;var a={en:[{id:`T063-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`RPC & gRPC`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Remote Procedure Call presents network operations as service methods; gRPC commonly uses Protocol Buffers, HTTP/2 and generated contracts.`},{id:`B`,text:`Rate limiting constrains request frequency or cost; throttling delays or rejects traffic to protect capacity and fairness.`},{id:`C`,text:`Backward compatibility lets newer systems continue serving existing clients and stored data.`},{id:`D`,text:`Authentication establishes who or what is making a request; authorization determines what that principal may do.`}]},{id:`T063-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`RPC & gRPC`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Model resource identity with URIs, use HTTP methods according to semantics, return appropriate status codes, support caching when correct, and expose links when hypermedia is part of the contract.`},{id:`B`,text:`Differentiate additive fields from removed fields, changed semantics and renamed enum values.`},{id:`C`,text:`Check token/session validity, then evaluate permissions against action, resource and context.`},{id:`D`,text:`Define service methods and schema evolution rules, propagate deadlines and cancellation, authenticate each call and understand streaming modes.`}]},{id:`T063-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which practical project example best illustrates `},{t:`RPC & gRPC`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`A dashboard can fetch booking details, guest name and payment status in one shaped query. Field-level checks must still prevent exposing private billing details to unauthorized staff.`},{id:`B`,text:`An analytics service can stream events to a processor through a typed gRPC endpoint, while the public frontend continues to use REST or GraphQL through a gateway.`},{id:`C`,text:`A reservation API may expose POST /reservations for creation, GET for reads, PATCH for partial changes, and a dedicated cancellation action when cancellation is a meaningful state transition.`},{id:`D`,text:`A public search API allows small bursts but caps sustained requests; a login endpoint additionally limits attempts per account and network source while detecting abuse.`}]},{id:`T063-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`RPC & gRPC`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`GraphQL does not automatically solve backend performance; arbitrary client queries can be expensive.`},{id:`B`,text:`Browser support, proxies, debugging and load balancing require special consideration.`},{id:`C`,text:`Client-side route guards improve UX but are not security controls.`},{id:`D`,text:`A timestamp alone is not unique and can cause skipped rows.`}]},{id:`T063-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It suits typed service-to-service APIs while retaining all realities of network failure.`}]}]},{id:`T063-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`gRPC always works without adaptation in every browser environment.`}]}]},{id:`T063-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Generated stubs do not replace compatibility tests or solve idempotency and timeout decisions.`}]}]},{id:`T063-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`RPC & gRPC`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Define service methods and schema evolution rules, propagate deadlines and cancellation, authenticate each call and understand streaming modes.`},{id:`B`,text:`RPC calls make partial network failures behave like local function errors.`},{id:`C`,text:`Remote Procedure Call presents network operations as service methods; gRPC commonly uses Protocol Buffers, HTTP/2 and generated contracts.`},{id:`D`,text:`A valid login token grants permission to read every tenant's data.`}]},{id:`T063-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`RPC & gRPC`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`gRPC always works without adaptation in every browser environment.`},{id:`B`,text:`Generated stubs do not replace compatibility tests or solve idempotency and timeout decisions.`},{id:`C`,text:`Authorization checks are only necessary on the login route.`},{id:`D`,text:`An analytics service can stream events to a processor through a typed gRPC endpoint, while the public frontend continues to use REST or GraphQL through a gateway.`}]},{id:`T063-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`An analytics service can stream events to a processor through a typed gRPC endpoint, while the public frontend continues to use REST or GraphQL through a gateway.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to design tenant-aware authorization for bookings, including service accounts and revoked permissions. Require tests for horizontal and vertical privilege escalation.`},{id:`B`,text:`Ask an agent to build a filtered booking endpoint with cursor pagination, stable sorting and tests for concurrent insert/delete between requests.`},{id:`C`,text:`Have an agent design a typed booking schema with batching, complexity limits and field authorization. Test nested query abuse and unauthorized field access.`},{id:`D`,text:`Have an agent specify a gRPC inventory API, with deadline propagation, backward-compatible field changes and tests for unavailable peers.`}]},{id:`T063-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Which parts of your RPC contract remain compatible when a new field is added?`}]}]},{id:`T063-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`An analytics service can stream events to a processor through a typed gRPC endpoint, while the public frontend continues to use REST or GraphQL through a gateway.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`RPC & gRPC`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T063-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`An analytics service can stream events to a processor through a typed gRPC endpoint, while the public frontend continues to use REST or GraphQL through a gateway.`,b:!0},{t:` — propose three checks for `},{t:`RPC & gRPC`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T063-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`An analytics service can stream events to a processor through a typed gRPC endpoint, while the public frontend continues to use REST or GraphQL through a gateway.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T063-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`RPC & gRPC`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`An analytics service can stream events to a processor through a typed gRPC endpoint, while the public frontend continues to use REST or GraphQL through a gateway.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T063-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`RPC та gRPC`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`RPC представляє мережеві операції як методи сервісу; gRPC часто використовує Protocol Buffers, HTTP/2 і згенеровані контракти.`},{id:`B`,text:`Rate limiting обмежує частоту або вартість запитів; throttling затримує чи відхиляє трафік, щоб захистити ресурси та справедливість.`},{id:`C`,text:`Зворотна сумісність дозволяє новій системі підтримувати старих клієнтів і дані.`},{id:`D`,text:`Автентифікація встановлює особу або сервіс, що робить запит; авторизація визначає дозволені дії.`}]},{id:`T063-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`RPC та gRPC`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Моделюйте ідентичність ресурсу через URI, дотримуйтеся семантики HTTP-методів, повертайте належні статуси, застосовуйте кешування, а посилання між ресурсами — коли це частина контракту.`},{id:`B`,text:`Відрізняйте додавання полів від видалення, змін семантики та перейменувань enum.`},{id:`C`,text:`Перевіряйте токен або сесію, потім оцінюйте дозвіл з огляду на дію, ресурс і контекст.`},{id:`D`,text:`Визначайте методи сервісу й правила еволюції схем, передавайте deadline та cancellation, автентифікуйте виклики й розумійте streaming.`}]},{id:`T063-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який приклад із практичного проєкту найкраще ілюструє `},{t:`RPC та gRPC`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Панель може одним запитом отримати бронювання, ім’я гостя й стан платежу. Перевірки на рівні полів повинні не допустити витоку приватних платіжних даних.`},{id:`B`,text:`Аналітичний сервіс може передавати події потоком через типізований gRPC endpoint, а зовнішній фронтенд — користуватися REST або GraphQL через gateway.`},{id:`C`,text:`API бронювань може надавати POST /reservations для створення, GET для читання, PATCH для часткових змін та окрему дію скасування, коли вона є повноцінним переходом стану.`},{id:`D`,text:`Публічний пошук дозволяє короткі піки, але обмежує тривале навантаження; login також лімітує спроби за акаунтом і джерелом та виявляє зловживання.`}]},{id:`T063-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`RPC та gRPC`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`GraphQL не прискорює бекенд автоматично: довільні запити можуть бути дорогими.`},{id:`B`,text:`Підтримка браузера, proxy, дебаг і балансування потребують уваги.`},{id:`C`,text:`Клієнтські route guards покращують UX, але не є захистом.`},{id:`D`,text:`Сам timestamp не унікальний і може пропускати записи.`}]},{id:`T063-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Це добре для типізованих міжсервісних API, але мережеві збої залишаються.`}]}]},{id:`T063-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`gRPC завжди без адаптації працює в будь-якому браузері.`}]}]},{id:`T063-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Згенеровані клієнти не замінюють тести сумісності та не вирішують питання ідемпотентності й timeout.`}]}]},{id:`T063-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`RPC та gRPC`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Визначайте методи сервісу й правила еволюції схем, передавайте deadline та cancellation, автентифікуйте виклики й розумійте streaming.`},{id:`B`,text:`RPC-виклики перетворюють часткові мережеві збої на звичайні локальні помилки функцій.`},{id:`C`,text:`RPC представляє мережеві операції як методи сервісу; gRPC часто використовує Protocol Buffers, HTTP/2 і згенеровані контракти.`},{id:`D`,text:`Чинний токен входу дозволяє читати дані будь-якого орендаря.`}]},{id:`T063-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`RPC та gRPC`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`gRPC завжди без адаптації працює в будь-якому браузері.`},{id:`B`,text:`Згенеровані клієнти не замінюють тести сумісності та не вирішують питання ідемпотентності й timeout.`},{id:`C`,text:`Перевіряти авторизацію потрібно лише на маршруті входу.`},{id:`D`,text:`Аналітичний сервіс може передавати події потоком через типізований gRPC endpoint, а зовнішній фронтенд — користуватися REST або GraphQL через gateway.`}]},{id:`T063-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Аналітичний сервіс може передавати події потоком через типізований gRPC endpoint, а зовнішній фронтенд — користуватися REST або GraphQL через gateway.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента спроєктувати tenant-aware авторизацію бронювань, включно із сервісними акаунтами та відкликаними правами. Вимагайте тести горизонтального й вертикального підвищення привілеїв.`},{id:`B`,text:`Попросіть агента зробити endpoint бронювань із фільтрами, cursor-пагінацією, стабільним порядком і тестами вставки/видалення між сторінками.`},{id:`C`,text:`Попросіть агента створити типізовану схему бронювань з batching, лімітами складності та авторизацією полів. Перевірте глибокі запити й несанкціонований доступ.`},{id:`D`,text:`Попросіть агента описати gRPC API складу з передаванням deadline, сумісними змінами полів і тестами недоступного сервісу.`}]},{id:`T063-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Які частини RPC-контракту залишаться сумісними після додавання поля?`}]}]},{id:`T063-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Аналітичний сервіс може передавати події потоком через типізований gRPC endpoint, а зовнішній фронтенд — користуватися REST або GraphQL через gateway.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`RPC та gRPC`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T063-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Аналітичний сервіс може передавати події потоком через типізований gRPC endpoint, а зовнішній фронтенд — користуватися REST або GraphQL через gateway.`,b:!0},{t:` запропонуйте три перевірки `},{t:`RPC та gRPC`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T063-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Аналітичний сервіс може передавати події потоком через типізований gRPC endpoint, а зовнішній фронтенд — користуватися REST або GraphQL через gateway.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T063-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`RPC та gRPC`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Аналітичний сервіс може передавати події потоком через типізований gRPC endpoint, а зовнішній фронтенд — користуватися REST або GraphQL через gateway.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var o={slug:i,topicId:63,questions:a};export{o as default,a as questions,i as slug,n as topicId};